import math
import time

from taf.rfrl.procedures.resources.python.rf_attenuator.device import Attenuator

from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result, log_operation, log_warning
from taf.rfrl.procedures.resources.python.rf_attenuator.exceptions import MissingAttenuatorSetup, \
    IncorrectAttenuationMode, IncorrectParameterValue


class RfAttenuator:
    def __init__(self):
        self._att_info = None
        self._att_config = None
        self._attenuator = None

    @log_input_and_output
    def att_setup(self, att_info, att_config):
        """
        Setups of attenuator device and creates Attenuator class instance.
        Setup procedure is required before starting other operations on the attenuator.
        :param att_info: attenuator object from testline configuration file
        :type att_info: attenuator object
        :param att_config: dictionary with configuration of attenuator ports, e.g.:
                          {"ports": [{"antenna": "ANTL-1", "port": 13, "OFF": 90, "DL": 0, "UL": 0},
                                     {"antenna": "ANTL-2", "port": 14, "OFF": 90, "DL": 0, "UL": 0},
                                     {"antenna": "ANTL-3", "port": 15, "OFF": 90, "DL": 0, "UL": 0},
                                     {"antenna": "ANTL-4", "port": 16, "OFF": 90, "DL": 0, "UL": 0}]}
        :type att_config: dict
        """
        if self._attenuator is None:
            self._att_info = att_info
            self._att_config = att_config
            self._attenuator = Attenuator(info=att_info, config=att_config)

    @log_input_and_output
    def get_att_ports_configuration(self):
        """
        Gets current configuration of all attenuator ports defined in setup.
        :returns: current configuration of attenuator ports, with port number as key and attenuation level as value,
                  e.g. : {13: 0, 14: 10, 15: 5, 16: 0}
        :rtype: dict
        :raises MissingAttenuatorSetup: when attenuator setup procedure was not run before.
        """
        self._verify_attenuator_setup()

        att_ports = [att_port["port"] for att_port in self._att_config["ports"]]

        startup_att_ports_setup = self._get_att_ports_configuration(att_ports=att_ports)

        return startup_att_ports_setup

    def set_all_attenuator_ports_to_chosen_mode(self, mode):
        """
        Sets attenuator ports according to given attenuation mode.
        :param mode: attenuation mode to set on all ports, e.g.: "off", "OFF", "dl" or "DL"
        :type mode: str

        :raises MissingAttenuatorSetup: when attenuator setup procedure was not run before.
        :raises IncorrectAttenuationMode: when attenuation mode was not defined for any attenuator port.
        """
        self._verify_attenuator_setup()
        mode = mode.upper()

        log_operation(f"Setting all attenuator ports to '{mode}' mode.")
        for port in self._att_config["ports"]:
            if port.get(mode) is not None:
                self._attenuator.set_attenuation_on_port(port=int(port["port"]), value_db=int(port[mode]))
            else:
                raise IncorrectAttenuationMode(f"Attenuation mode '{mode}' was not defined for port '{port['port']}' "
                                               f"in attenuator configuration: {self._att_config}")

    @log_input_and_output
    def set_attenuation_on_ports(self, att_ports_configuration):
        """
        Sets attenuator ports according to given ports configuration.
        :param att_ports_configuration: attenuator ports configuration with port number as key and attenuation
                                        level as value, e.g. : {13: 0, 14: 10, 15: 5, 16: 0}
        :type att_ports_configuration: dict
        :raises MissingAttenuatorSetup: when attenuator setup procedure was not run before.
        """
        self._verify_attenuator_setup()

        for att_port, att_value in att_ports_configuration.items():
            log_operation(f"Setting attenuation on port '{att_port}': {att_value}dB...")
            self._attenuator.set_attenuation_on_port(port=int(att_port), value_db=int(att_value))

    @log_input_and_output
    def decrease_gradually_attenuation_for_all_rf_ports(self, att_value, count_of_steps=1, timeout=15):
        """
        Decreases the attenuation logarithmically on given all attenuator ports defined in setup.
        :param att_value: level of attenuation (in decibels) to decrease on all attenuator ports defined in setup.
        :type att_value: int
        :param count_of_steps: count of steps to decrease attenuation to target level. The attenuation level will
                               decrease logarithmically for a certain number of steps. Defaults to 1 means that the
                               attenuation target level will be obtained immediately after the first attenuation change.
        :type count_of_steps: int or str
        :param timeout: total time (in seconds) to wait for attenuation change operation and achieve target attenuation
                        value on all attenuator ports. Defaults to 15.
                        The warning message will be logged when attenuation change on all ports takes more time than
                        timeout/count_of_steps - finally all attenuation steps will be performed but overall operation
                        may take an uncontrolled amount of time. In case of count_of_steps equal 1, timeout check will
                        be skipped and operation will take only as much time as it takes to change the value on the
                        attenuator hardware.
        :type timeout: int or str
        :raises MissingAttenuatorSetup: when attenuator setup procedure was not run before.
        """
        self._verify_attenuator_setup()

        time_before_next_step = int(timeout) / int(count_of_steps)
        self._modify_attenuation_for_rf_signal_logarithmic(operation="decrease", att_value=att_value,
                                                           count_of_steps=int(count_of_steps),
                                                           time_before_next_step=time_before_next_step)

    @log_input_and_output
    def increase_gradually_attenuation_for_all_rf_ports(self, att_value, count_of_steps=1, timeout=15):
        """
        Increases the attenuation logarithmically on all attenuator ports defined in setup.
        :param att_value: level of attenuation (in decibels) to increase on all attenuator ports defined in setup.
        :type att_value: int
        :param count_of_steps: count of steps to increase attenuation to target level. The attenuation level will
                               increase logarithmically in a certain number of steps. Defaults to 1 means that the
                               attenuation target level will be obtained immediately after the first attenuation change.
        :type count_of_steps: int or str
        :param timeout: total time (in seconds) to wait for attenuation change operation and achieve target attenuation
                        value on all attenuator ports. Defaults to 15.
                        The warning message will be logged when attenuation change on all ports takes more time than
                        timeout/count_of_steps - finally all attenuation steps will be performed but overall operation
                        may take an uncontrolled amount of time. In case of count_of_steps equal 1, timeout check will
                        be skipped and operation will take only as much time as it takes to change the value on the
                        attenuator hardware.
        :type timeout: int or str

        :raises MissingAttenuatorSetup: when attenuator setup procedure was not run before.
        """
        self._verify_attenuator_setup()

        time_before_next_step = int(timeout) / int(count_of_steps)
        self._modify_attenuation_for_rf_signal_logarithmic(operation="increase", att_value=att_value,
                                                           count_of_steps=int(count_of_steps),
                                                           time_before_next_step=time_before_next_step)

    @log_input_and_output
    def _modify_attenuation_for_rf_signal_logarithmic(self, operation, att_value, count_of_steps=1,
                                                      time_before_next_step=15):
        """
        Modifies attenuation logarithmically on given all attenuator ports defined in setup.
        :param operation: the way of attenuation modification, one of following: "increase" or "decrease"
        :type operation: str
        :param att_value: level of attenuation (in decibels) to decrease on all attenuator ports defined in setup.
        :type att_value: int
        :param count_of_steps: count of steps to decrease attenuation to target level. The attenuation level will
                               decrease logarithmically for a certain number of steps. Defaults to 1 means that the
                               attenuation target level will be obtained immediately after the first attenuation change.
        :type count_of_steps: int
        :param time_before_next_step: time (in seconds) to wait before next attenuation change step. The warning message
                                      will be logged when attenuation change on all ports takes more time than
                                      `time_before_next_step` parameter value - finally all attenuation steps will be
                                      performed but overall operation may take an uncontrolled amount of time.
                                      In case of count_of_steps equal 1, next step waiting time will be skipped.
                                      Defaults to 15.
        :type time_before_next_step: int
        :raises IncorrectParameterValue: when 'operation' parameter has incorrect value.
        """
        if operation not in ["increase", "decrease"]:
            raise IncorrectParameterValue(f"Incorrect 'operation' parameter: {operation}")

        startup_att_ports_setup = self._get_att_ports_configuration([att_port["port"]
                                                                     for att_port in self._att_config["ports"]])
        log_result(f"Initial attenuator ports setup: {startup_att_ports_setup}")

        power_level = self._convert_db_to_p(att_value)
        att_steps_db = {x: round(self._convert_p_to_db(power_level * x / int(count_of_steps)))
                        for x in range(1, int(count_of_steps) + 1)}
        log_result(f"Attenuation step levels to set on ports: {att_steps_db}")

        for step, step_value in att_steps_db.items():
            log_operation(f"STEP {step}: Setting attenuator ports: {list(startup_att_ports_setup.keys())}...")
            start_time = time.time()
            for att_port, startup_lvl in startup_att_ports_setup.items():
                target_value = (startup_lvl + step_value) if operation == "increase" else (startup_lvl - step_value)
                self._attenuator.set_attenuation_on_port(port=att_port, value_db=target_value)
                log_result(f"Attenuation on port {att_port} has been set to {target_value}dB")

            if step < int(count_of_steps):
                self._wait_for_step_time(start_time=start_time, step_time=int(time_before_next_step))

    def _get_att_ports_configuration(self, att_ports):
        """
        Gets current configuration of particular attenuator ports defined in setup.
        :param att_ports: list of attenuator ports to get configuration, e.g.: [13, 14, 15]
        :type att_ports: list
        :returns: current configuration of particular attenuator ports, with port number as key and attenuation level
                  as value, e.g. : {13: 0, 14: 10, 15: 5}
        :rtype: dict
        """
        startup_att_ports_setup = {}
        for att_port in att_ports:
            startup_att_ports_setup[att_port] = self._attenuator.get_attenuation_on_port(port=att_port)

        return startup_att_ports_setup

    def _verify_attenuator_setup(self):
        """
        Verifies if attenuator setup has been performed.

        :raises MissingAttenuatorSetup: when attenuator setup was not yet performed.
        """
        if self._attenuator is None:
            raise MissingAttenuatorSetup("Missing attenuator setup! Please use `att_setup` first.")

    @staticmethod
    def _wait_for_step_time(start_time, step_time):
        """
        Waits for next attenuation step. Logs warning message if attenuation change operation takes more time than
        defined step_time.
        :param start_time: start time of current attenuation step
        :type start_time: datetime
        :param step_time: time (in seconds) to wait before next attenuation change step. The warning message
                          will be logged when attenuation change on all ports takes more time than
                          `step_time` parameter value.
        :type step_time: int
        """
        current_time = time.time()
        delta_time = current_time - start_time

        if delta_time < step_time:
            log_operation("Waiting after attenuator ports setup...")
            time.sleep(step_time - delta_time)
        elif delta_time > step_time:
            log_warning("Step time is too short to setup all attenuator ports. "
                        "Operation may exceed the estimated total time!")

    @staticmethod
    def _convert_db_to_p(db_value):
        """
        Converts decibels to power (watts) value.
        :param db_value: value of decibels to convert
        :type db_value: float, int or str
        """
        return 10 ** (float(db_value) / 10)

    @staticmethod
    def _convert_p_to_db(p_value):
        """
        Converts power (watts) to decibels value.
        :param p_value: value of power (watts) to convert
        :type p_value: float, int or str
        """
        return 10 * math.log(float(p_value), 10)
